      border: 1px solid rgba(20, 32, 51, 0.14);
      border-radius: 24px;
      padding: 0;
      background: var(--surface-strong);
      color: var(--text);
      box-shadow: 0 40px 90px rgba(10, 16, 28, 0.34);
    }

    dialog::backdrop {
      background: var(--backdrop);
      backdrop-filter: blur(4px);
    }

    .dialog {
      padding: 24px;
      display: grid;
      gap: 18px;
    }

    .dialog h2 {
      margin: 0;
      font-size: 1.4rem;
      line-height: 1.2;
    }

    .dialog p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      gap: 12px;
      justify-content: flex-end;
      flex-wrap: wrap;
    }

    .dialog button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 12px 18px;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 160ms ease, background-color 160ms ease, box-shadow 160ms ease;
